FONTS={'graduate':'Graduate','russo':'Russo One','alfa':'Alfa Slab One','righteous':'Righteous','rye':'Rye','staat':'Staatliches'}
app=open('site/assets/app.js').read()
names=dict(re.findall(r"([A-Z]{2,3}): '([^']+)'", re.search(r"const NFL_NAMES = \{(.*?)\};",app,re.S).group(1)))
cols={k:re.findall(r"'(#[0-9A-Fa-f]{3,6})'",v) for k,v in re.findall(r"([A-Z]{2,3}): \[([^\]]*)\]", re.search(r"const NFLC = \{(.*?)\};",app,re.S).group(1))}
def lum(h):
    h=h.lstrip('#'); h=''.join(c*2 for c in h) if len(h)==3 else h
    r,g,b=[int(h[i:i+2],16)/255 for i in (0,2,4)]; f=lambda c: c/12.92 if c<=.03928 else ((c+.055)/1.055)**2.4
    return .2126*f(r)+.7152*f(g)+.0722*f(b)
def contrast(a,b): la,lb=sorted([lum(a),lum(b)],reverse=True); return (la+.05)/(lb+.05)
out={}
for ab,(what,font,svg) in sorted(E.items()):
    p,s=cols[ab][0],cols[ab][1]
    e=s if contrast(p,s)>=3 else '#ffffff'          # emblem colour: the second colour when it stands out on the first, else white
    t='#ffffff' if contrast(p,'#ffffff')>=4.5 else '#101010'
    ring=s if contrast(p,s)>=1.6 else '#ffffff'
    out[ab]={'name':names.get(ab,ab),'emblem':svg,'what':what,'font':FONTS[font],'p':p,'s':s,'e':e,'t':t,'ring':ring}
assert len(out)==32, len(out)
json.dump(out,open('src/nfl-badges/badges.json','w'),indent=1)
ff=''.join(f"@font-face{{font-family:'{n}';src:url('/tmp/fonts/node_modules/@fontsource/{d}/files/{d}-latin-400-normal.woff2') format('woff2')}}" for n,d in [('Graduate','graduate'),('Russo One','russo-one'),('Alfa Slab One','alfa-slab-one'),('Righteous','righteous'),('Rye','rye'),('Staatliches','staatliches')])
card=lambda ab,b: f'''<div class="c" style="--p:{b['p']};--s:{b['s']}"><div class="patch" style="border-color:{b['ring']};color:{b['e']}"><svg viewBox="0 0 100 100">{b['emblem']}</svg><b style="font-family:'{b['font']}';color:{b['t']}">{ab}</b></div><div class="mini" style="color:{b['t']};font-family:'{b['font']}';box-shadow:inset 0 0 0 2px {b['ring']}">{ab}</div><small>{b['what']}</small></div>'''
html=f'''<!doctype html><meta charset="utf-8"><style>{ff}body{{margin:0;padding:28px;background:#f1eee7;font-family:system-ui,sans-serif}}h1{{font:600 26px system-ui;margin:0 0 4px}}p{{margin:0 0 20px;color:#565c68;font-size:15px}}
.g{{display:grid;grid-template-columns:repeat(8,1fr);gap:18px}}.c{{background:#fff;border:1px solid #dcd8cf;border-radius:14px;padding:14px 8px 10px;display:flex;flex-direction:column;align-items:center;gap:9px}}
.patch{{width:112px;height:128px;border-radius:16px;background:var(--p);border:4px solid;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;box-sizing:border-box}}.patch svg{{width:66px;height:66px}}.patch b{{font-size:26px;font-weight:400;line-height:1;letter-spacing:.04em}}
.mini{{height:24px;min-width:44px;padding:0 8px;border-radius:6px;background:var(--p);display:flex;align-items:center;justify-content:center;font-size:13px;letter-spacing:.05em}}small{{font-size:12px;color:#565c68;text-align:center}}</style>
<h1>NYC Dynasty League · original NFL team badges (review set)</h1><p>Large patch for films and features; small abbreviation tag for use beside player names. Emblems are drawn from city and fan identity, not from any club's mascot or mark.</p><div class="g">{''.join(card(a,b) for a,b in out.items())}</div>'''
open('/tmp/badges_review.html','w').write(html); print('ok',len(out))
